-- CityShield schema (MySQL 8 / H2 MySQL-mode). GENERATED by data/tools/generate_backend_code.py from spec.py.
-- Only CREATE TABLE IF NOT EXISTS: existing data is never dropped or altered.

CREATE TABLE IF NOT EXISTS city_zones (
  zone_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(80) NOT NULL UNIQUE,
  zone_index INT NOT NULL UNIQUE,
  latitude DOUBLE NOT NULL,
  longitude DOUBLE NOT NULL,
  zone_role VARCHAR(12) NOT NULL,
  population INT NOT NULL,
  CONSTRAINT ck_city_zones_latitude CHECK (latitude BETWEEN 18 AND 20),
  CONSTRAINT ck_city_zones_longitude CHECK (longitude BETWEEN 72 AND 74),
  CONSTRAINT ck_city_zones_zone_role CHECK (zone_role IN ('WAREHOUSE','HUB','DEMAND')),
  CONSTRAINT ck_city_zones_population CHECK (population >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS road_connections (
  road_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  zone_a BIGINT NOT NULL,
  zone_b BIGINT NOT NULL,
  distance_km DOUBLE NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'OPEN',
  CONSTRAINT fk_road_connections_zone_a FOREIGN KEY (zone_a) REFERENCES city_zones(zone_id),
  CONSTRAINT fk_road_connections_zone_b FOREIGN KEY (zone_b) REFERENCES city_zones(zone_id),
  CONSTRAINT ck_road_connections_distance_km CHECK (distance_km > 0),
  CONSTRAINT ck_road_connections_status CHECK (status IN ('OPEN','BLOCKED')),
  CONSTRAINT ck_road_distinct CHECK (zone_a <> zone_b),
  CONSTRAINT uq_road_pair UNIQUE (zone_a, zone_b),
  INDEX ix_road_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS distribution_edges (
  edge_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  from_zone BIGINT NOT NULL,
  to_zone BIGINT NOT NULL,
  capacity_units INT NOT NULL,
  CONSTRAINT fk_distribution_edges_from_zone FOREIGN KEY (from_zone) REFERENCES city_zones(zone_id),
  CONSTRAINT fk_distribution_edges_to_zone FOREIGN KEY (to_zone) REFERENCES city_zones(zone_id),
  CONSTRAINT ck_distribution_edges_capacity_units CHECK (capacity_units >= 0),
  CONSTRAINT ck_edge_distinct CHECK (from_zone <> to_zone),
  CONSTRAINT uq_edge_pair UNIQUE (from_zone, to_zone)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS emergency_centres (
  centre_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  zone_id BIGINT NOT NULL,
  coverage_radius_km DOUBLE NOT NULL,
  cost DOUBLE NOT NULL,
  status VARCHAR(12) NOT NULL,
  centre_type VARCHAR(20) NOT NULL,
  CONSTRAINT fk_emergency_centres_zone_id FOREIGN KEY (zone_id) REFERENCES city_zones(zone_id),
  CONSTRAINT ck_emergency_centres_coverage_radius_km CHECK (coverage_radius_km > 0),
  CONSTRAINT ck_emergency_centres_cost CHECK (cost >= 0),
  CONSTRAINT ck_emergency_centres_status CHECK (status IN ('EXISTING','PROPOSED','UNAVAILABLE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS hospitals (
  hospital_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  zone_id BIGINT NOT NULL,
  bed_capacity INT NOT NULL,
  beds_available INT NOT NULL,
  CONSTRAINT fk_hospitals_zone_id FOREIGN KEY (zone_id) REFERENCES city_zones(zone_id),
  CONSTRAINT ck_hospitals_bed_capacity CHECK (bed_capacity >= 0),
  CONSTRAINT ck_hospitals_beds_available CHECK (beds_available >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS emergency_types (
  type_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(24) NOT NULL UNIQUE,
  name VARCHAR(60) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS emergency_type_team_compat (
  compat_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  type_id BIGINT NOT NULL,
  team_type VARCHAR(16) NOT NULL,
  CONSTRAINT fk_emergency_type_team_compat_type_id FOREIGN KEY (type_id) REFERENCES emergency_types(type_id),
  CONSTRAINT uq_compat UNIQUE (type_id, team_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS resource_types (
  resource_type_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(60) NOT NULL UNIQUE,
  unit VARCHAR(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS resource_inventory (
  inventory_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  zone_id BIGINT NOT NULL,
  resource_type_id BIGINT NOT NULL,
  quantity_available INT NOT NULL,
  quantity_capacity INT NOT NULL,
  CONSTRAINT fk_resource_inventory_zone_id FOREIGN KEY (zone_id) REFERENCES city_zones(zone_id),
  CONSTRAINT fk_resource_inventory_resource_type_id FOREIGN KEY (resource_type_id) REFERENCES resource_types(resource_type_id),
  CONSTRAINT ck_resource_inventory_quantity_available CHECK (quantity_available >= 0),
  CONSTRAINT ck_resource_inventory_quantity_capacity CHECK (quantity_capacity >= 0),
  CONSTRAINT uq_inventory UNIQUE (zone_id, resource_type_id),
  CONSTRAINT ck_inv_cap CHECK (quantity_available <= quantity_capacity)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS response_teams (
  team_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(80) NOT NULL UNIQUE,
  team_type VARCHAR(16) NOT NULL,
  base_zone_id BIGINT NOT NULL,
  centre_id BIGINT,
  availability VARCHAR(12) NOT NULL DEFAULT 'AVAILABLE',
  current_incident_id BIGINT,
  CONSTRAINT fk_response_teams_base_zone_id FOREIGN KEY (base_zone_id) REFERENCES city_zones(zone_id),
  CONSTRAINT fk_response_teams_centre_id FOREIGN KEY (centre_id) REFERENCES emergency_centres(centre_id),
  CONSTRAINT ck_response_teams_team_type CHECK (team_type IN ('FIRE','MEDICAL','RESCUE','POLICE','HAZMAT','ENGINEERING')),
  CONSTRAINT ck_response_teams_availability CHECK (availability IN ('AVAILABLE','BUSY','OFF_DUTY')),
  INDEX ix_team_avail (availability, team_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS emergency_incidents (
  incident_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  incident_code VARCHAR(20) NOT NULL UNIQUE,
  type_id BIGINT NOT NULL,
  zone_id BIGINT NOT NULL,
  description VARCHAR(500) NOT NULL,
  severity INT NOT NULL,
  urgency INT NOT NULL,
  affected_people INT NOT NULL,
  status VARCHAR(12) NOT NULL,
  reported_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL,
  updated_at DATETIME NOT NULL,
  CONSTRAINT fk_emergency_incidents_type_id FOREIGN KEY (type_id) REFERENCES emergency_types(type_id),
  CONSTRAINT fk_emergency_incidents_zone_id FOREIGN KEY (zone_id) REFERENCES city_zones(zone_id),
  CONSTRAINT ck_emergency_incidents_severity CHECK (severity BETWEEN 1 AND 5),
  CONSTRAINT ck_emergency_incidents_urgency CHECK (urgency BETWEEN 1 AND 5),
  CONSTRAINT ck_emergency_incidents_affected_people CHECK (affected_people >= 0),
  CONSTRAINT ck_emergency_incidents_status CHECK (status IN ('REPORTED','ASSIGNED','IN_PROGRESS','RESOLVED','CANCELLED','ARCHIVED')),
  INDEX ix_inc_status (status),
  INDEX ix_inc_zone (zone_id),
  INDEX ix_inc_reported (reported_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

