  CONSTRAINT ck_incident_resource_requirements_quantity_required CHECK (quantity_required > 0),
  CONSTRAINT uq_requirement UNIQUE (incident_id, resource_type_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

