  CONSTRAINT fk_incident_assignments_incident_id FOREIGN KEY (incident_id) REFERENCES emergency_incidents(incident_id),
  CONSTRAINT fk_incident_assignments_team_id FOREIGN KEY (team_id) REFERENCES response_teams(team_id),
